rules.language.schema.json:
{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "语言学习共享内容",
  "description": "一个选定目标的读音、语境义及必要时生成的例句；来源原文由应用保存。",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "pronunciation",
    "meaning",
    "generatedSentence",
    "generatedTargetStart"
  ],
  "properties": {
    "pronunciation": {
      "title": "读音",
      "description": "目标在本次语境中的完整读音。中文单个词的各音节必须连写，只有不同词之间才用空格；英文只写斜线内的 IPA，混合目标按原顺序组合。不得附原始目标拼写。",
      "type": "string",
      "minLength": 1,
      "pattern": "\\S"
    },
    "meaning": {
      "title": "语境义",
      "description": "目标在本次语境中的简洁中文改述或表达作用，也作为书写回忆提示。不能带入英文拼写或英文原形，不能照抄目标实义词；保持本次词性、语态和程度准确，不夸大为必然结果。",
      "type": "string",
      "minLength": 1,
      "pattern": "\\S"
    },
    "generatedSentence": {
      "title": "AI 生成例句",
      "description": "真实或用户上下文存在时为 null；仅在获准生成且没有上下文时提供含目标原样文本的自然例句。",
      "type": ["string", "null"],
      "minLength": 1,
      "pattern": "\\S"
    },
    "generatedTargetStart": {
      "title": "例句中目标的起始位置",
      "description": "模型返回 null；获准生成的例句必须含且仅含一次原样目标，由应用确定其 UTF-16 下标。兼容旧整数输出，但以应用的唯一精确匹配为准。",
      "type": ["integer", "null"],
      "minimum": 0
    }
  },
  "anyOf": [
    {
      "properties": {
        "generatedSentence": {"type": "null"},
        "generatedTargetStart": {"type": "null"}
      }
    },
    {
      "properties": {
        "generatedSentence": {"type": "string"},
        "generatedTargetStart": {"type": ["integer", "null"]}
      }
    }
  ]
}

rules.ocr-cleanup.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "OCR 清洗内容结果",
  "description": "专用内容字段；不是 excerpt-card 的单卡结构。",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "cleaned_text",
    "notes"
  ],
  "properties": {
    "cleaned_text": {
      "type": "string",
      "description": "完整清洗文字；只有输入为空时允许为空。"
    },
    "notes": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "source_quote",
          "reason"
        ],
        "properties": {
          "source_quote": {
            "type": "string",
            "minLength": 1,
            "description": "必须逐字连续来自本次 ocr_text；来源匹配由调用方检查。"
          },
          "reason": {
            "type": "string",
            "minLength": 1,
            "pattern": "\\S"
          }
        }
      }
    }
  }
}

rules.question.schema.json:
{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "当前问题的回答",
  "description": "只承载本轮答案及未解决原因，不包含历史问答或卡片结构。",
  "type": "object",
  "additionalProperties": false,
  "required": ["answer_state", "answer_text", "unresolved_reasons"],
  "properties": {
    "answer_state": {
      "title": "回答状态",
      "type": "string",
      "enum": ["answered", "unresolved"]
    },
    "answer_text": {
      "title": "本轮答案",
      "description": "answered 时为非空纯文本；unresolved 时为 null。",
      "type": ["string", "null"],
      "minLength": 1,
      "pattern": "\\S"
    },
    "unresolved_reasons": {
      "title": "未解决原因",
      "description": "answered 时为空数组；unresolved 时至少提供一个简短、稳定的机器原因。",
      "type": "array",
      "items": {"type": "string", "minLength": 1, "pattern": "\\S"}
    }
  },
  "oneOf": [
    {
      "properties": {
        "answer_state": {"enum": ["answered"]},
        "answer_text": {"type": "string"},
        "unresolved_reasons": {"type": "array", "maxItems": 0, "enum": [[]]}
      }
    },
    {
      "properties": {
        "answer_state": {"enum": ["unresolved"]},
        "answer_text": {"type": "null"},
        "unresolved_reasons": {"minItems": 1}
      }
    }
  ]
}

rules.translation.schema.json:
{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "中文译英文",
  "description": "本次完整材料的英文译文。",
  "type": "object",
  "additionalProperties": false,
  "required": ["translation"],
  "properties": {
    "translation": {
      "title": "英文译文",
      "description": "保留本次完整原意的自然英文译文，不附原文、解释或卡片字段。",
      "type": "string",
      "minLength": 1,
      "pattern": "\\S"
    }
  }
}
